def max_value_on_paths(N, grid_values):
    # Initialize the dp table with all zeros
    dp = [[0] * N for _ in range(N)]

    # Loop through the grid values and update the dp table
    for x, y, value in grid_values:
        dp[y][x] = value

    # Loop through the dp table in the reverse order
    # to find the maximum sum of values collected on two paths
    max_sum = 0
    for y in range(N-1, -1, -1):
        for x in range(N):
            if x == N-1 and y == N-1:
                continue
            if x == N-1:
                max_sum = max(max_sum, dp[y][x] + dp[y+1][x])
            elif y == N-1:
                max_sum = max(max_sum, dp[y][x] + dp[y][x+1])
            else:
                max_sum = max(max_sum, dp[y][x] + dp[y+1][x] + dp[y][x+1])

    return max_sum

