def verify_isbn(isbn: str) -> str:
    # Check if the provided ISBN is in the correct format
    if not isbn.isdigit() or len(isbn) != 10:
        return "Wrong format"

    # Calculate the checksum digit
    total = 0
    for i, digit in enumerate(isbn):
        if i % 2 == 0:
            total += int(digit)
        else:
            total += int(digit) * 3

    # Check if the checksum digit is correct
    if total % 10 == 0:
        return "Right"
    else:
        # Correct the checksum digit
        checksum = 10 - (total % 10)
        return isbn[:-1] + str(checksum)

