def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Create a 2D array to store the maximum volume that can be occupied by any subset of items
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Initialize the first row and column of the array
    for i in range(n + 1):
        dp[0][i] = 0
    for i in range(1, n + 1):
        dp[i][0] = volumes[i - 1]

    # Fill in the rest of the array using the dynamic programming approach
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + volumes[j - 1])

    # Return the minimum remaining space in the box
    return V - dp[n][n]

